/*
 * This program simulates how the money in an account grows over time,
 * assuming that the interest is compounded annually.
 * 
 * We've added some error checking (input validation) to ensure that the user enters
 * a non-negative value for the starting balance.
 */
import java.util.Scanner;

public class CompoundInterest {

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);

		// Here's a deluxe version that also keeps track of the number of invalid entries made by the user!
		// The user is given a maximum of 3 invalid tries before the program exits.
		double balance;
		int invalidTries = 0;
		do {
			System.out.println("Enter starting amount of money:");
			balance = s.nextDouble();
			if (balance < 0) {
				System.out.println("The balance must be a non-negative value!");
				invalidTries++;
			}

			if (invalidTries >= 3) {
				System.out.println("You have exceeded the limits of my patience for incompetence.");
				System.exit(1);	
			}
		} while (balance < 0);

		System.out.println("Enter the annual rate of growth (as a decimal):");
		double rate = s.nextDouble();
		System.out.println("Enter how much extra to throw in at the end of each year:");
		double extra = s.nextDouble();
		System.out.println("How many years would you like this to grow?");
		int years = s.nextInt();

		int y = 1;
		while (y <= years) {	// This loop repeats "years" times
			double startingBalance = balance;
			double interest = balance*rate;
			balance = startingBalance + interest + extra;	
			System.out.format("%3d  $%12.2f  $%12.2f  $%12.2f  $%12.2f\n", y, startingBalance, interest, extra, balance);
			y++;
		}
	}
}

/*
 * Checks whether a user-entered integer is prime.
 * A prime number is divisible by only itself and 1.
 *  2 is the smallest (and the only even) prime number.
 */
import java.util.Scanner;

public class PrimeChecker {

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);

		// Get user input for a number to check
		System.out.println("Enter a number to check:");
		int num = s.nextInt();

		boolean divisorFound = false;	
		for (int d = 2; d < num; d++) {	
			if (num % d == 0) {			
				divisorFound = true;
				break;
			}
		}

		// If we make it through the entire loop without finding a working divisor, divisorFound
		//  will still have its original value of false.

		if (!divisorFound) {	
			System.out.println(num + " is prime!");
		} else {
			System.out.println(num + " is not prime!");
		}
	}
}

/* 
 * Some basic demos of string operations.
 * 
 */
public class StringDemos {

	public static void main(String[] args) {

		String sentence = "sloths are soooo nice";

		// charAt allows you to retrieve a single char from a string.  charAt
		//  requires the index of the character to retrieve.  The index refers to
		//  the location of the character within the string; the first index is 0,
		//  and the indices count up by 1 from there.
		System.out.println(sentence.charAt(3));
		System.out.println(sentence.charAt(0));
		System.out.println(sentence.charAt(6));

		// length gives you the number of characters in the string (spaces count
		//  as characters too!)  Because indices start counting from 0, the index
		//  of the last character is always one less than the length of the string.
		System.out.println(sentence.length());

		// substring allows you to get part of the original string.
		// There are two versions:
		//  x.substring(i) gives you the substring from index i (inclusive) of string x,
		//   all the way to the end
		//  x.substring(i, j) gives you the substring from index i (inclusive) to index
		//   j (exclusive) of x.  The length of this substring is (j - i).
		System.out.println(sentence.substring(1));
		System.out.println(sentence.substring(7, 10));
	}

}

