/* 
 * Some more examples of methods, including recursive methods.
 * 
 * A recursive method is a method that calls itself in its own definition.
 * 
 */
public class MoreMethods {

	// This method returns a Pig Latin version of the parameter.  We use only
	//  one Pig Latin rule: move the first letter of the word to the end, and
	//  add "ay" after that.
	public static String pigLatinize(String something) {
		return something.substring(1) + "-" + something.charAt(0) + "ay";
	}

	public static double max(double a, double b, double c) {
		if (a >= b && a >= c)
			return a;
		else if (b >= a && b >= c)
			return b;
		else
			return c;
	}


	// Several overloaded versions of print - these methods don't return anything,
	//  so their return type is void.
	public static void print(String something) {
		System.out.println(something);
	}

	public static void print(int something) {
		System.out.println(something);
	}

	public static void print(char something) {
		System.out.println(something);
	}


	public static int factorial(int n) {
		if (n == 0)	
			return 1;
		else
			return n*factorial(n-1);
	}

	// Recursively computes the nth Fibonacci number.  The Fibonacci sequence
	//  starts with 0, 1, and each subsequent number is computed by adding the
	//  two previous numbers.
	// (The "0th" Fibonacci number is 0, and the "1st" Fibonacci number is 1.)
	public static int fibo(int n) {
		if (n == 0)	
			return 0;
		else if (n == 1)
			return 1;
		else
			return fibo(n-1) + fibo(n-2);
	}

	public static void main(String[] args) {
		// The recursive Fibonacci method is very inefficient!
		for (int i = 0; i < 100; i++)
			System.out.println(fibo(i));

	}
}

/*
 * Demo of how to define your own methods.
 */
import java.util.Scanner;

public class PizzaPrices {

	// The first line of a method definition is called the header.
	// The header includes "public static" (more on what this means later),
	//  followed by the method's return type, followed by the method's name,
	//  followed by a list of the method's parameters.
	public static double pizzaCost(int toppings) {
		// The method body indicates what to do with the parameters.
		double cost = 5.46 + 1*toppings;
		return cost;
	}

	// This is an overloaded version of the pizzaCost method.  Method
	//  overloading means defining more than one version of the same method that
	//  differ in their parameter quantity and/or type.  Java determines
	//  which version to use based on the arguments provided when you call
	//  the method.
	public static double pizzaCost(int toppings, String size) {
		double basePrice, toppingPrice;
		if (size.equalsIgnoreCase("S")) {
			basePrice = 5.46;
			toppingPrice = 1;
		} else if (size.equalsIgnoreCase("M")) {
			basePrice = 8;
			toppingPrice = 1.5;
		} else if (size.equalsIgnoreCase("L")) {
			basePrice = 10;
			toppingPrice = 2;
		} else {
			basePrice = 30;
			toppingPrice = 7.5;
		}

		double cost = basePrice + toppingPrice*toppings;
		return cost;
	}

	public static void main(String[] args) {
		Scanner yum = new Scanner(System.in);
		System.out.println("What size of pizza do you want? (S, M, L, USA)");
		String size = yum.nextLine();
		System.out.println("How many toppings?");
		int numSloths = yum.nextInt();

		// This is an example of a method call.  To call a method, just type its
		//  name followed by the inputs you want to use.  The inputs here are known
		//  as arguments.
		double cost = pizzaCost(numSloths, size);
		System.out.println(cost);
		double bigOrderPrice = 7*pizzaCost(5, "L") + 40*pizzaCost(10, "USA") + pizzaCost(1, "S");
	}
}

/*
 * Gets user input for 4 numbers and stores them into an array.
 * The program then displays those 4 numbers backwards.
 * 
 */
import java.util.Scanner;

public class ShowBackwards {

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);

		int[] x = new int[4];	

		// Get user input for each number and store it into the array
		for (int i = 0; i < x.length; i++) {
			System.out.println("Enter the next integer:");
			x[i] = s.nextInt();
		}

		// Print the array backwards
		for (int i = x.length - 1; i >= 0; i--)
			System.out.println(x[i]);
	}
}

/*
 * Demo of how Java handles pass-by-value in methods.
 * "Pass-by-value" means that when a method is called, the values of the arguments
 * get copied to the parameters of the method.  The method does its work using its
 * own copy of the parameters, meaning that the original arguments are not affected.
 */
public class ParamPassing {

	// This swap method performs its actions on its own copies of the
	//  variables x and y, so x and y from main are not affected.
	public static void swap(int x, int y) {
		System.out.println("in swap: x = " + x + ", y = " + y);
		int temp = x;
		x = y;
		y = temp;
		System.out.println("in swap: x = " + x + ", y = " + y);
	}

	// This swap method performs its actions on its own copies of the
	//  variables x, index1, and index2.  However, because array variables
	//  are references, the copy of x still points to the same block of memory
	//  as the x reference in main.  Hence, the x in main *is* affected.
	public static void swap(int[] x, int index1, int index2)
	{
		int temp = x[index1];
		x[index1] = x[index2];
		x[index2] = temp;
	}

	public static void main(String[] args) {

		int[] x = {10, 7, 13, 9, 4};
		System.out.println("in main: x[2] = " + x[2] + ", x[4] = " + x[4]);
		swap(x, 2, 4);
		System.out.println("in main: x[2] = " + x[2] + ", x[4] = " + x[4]);
	}
}

/*
 * Some examples of basic 2D array syntax.
 * 
 */
public class Arrays2D {

	// This method finds and returns the max element from the 2D array x.
	public static int findMax(int[][] x) {
		int max = x[0][0];

		// Go through the entire array, replacing max every time we see a higher element.
		for (int i = 0; i < x.length; i++) {
			for (int j = 0; j < x[i].length; j++) {
				if (x[i][j] > max)
					max = x[i][j];
			}
		}

		return max;
	}

	public static void main(String[] args) {
		// 2D array of 2 rows and 4 columns (default value is 0 since data type is int)
//		int[][] x = new int[2][4];
//		x[0][1] = 10;	// Change the value of row 0, col 1

		// Shorthand way of initializing a 2D array with known values
		int[][] x = { {7, 10, 9, 4}, {2, 3, 8, 6} };

		// How to iterate through all elements of a 2D array
		//  x.length = number of rows of x
		//  x[i].length = number of columns in row i of x
		//   (you could replace this with x[0].length, if you know that all
		//    rows have the same number of columns)
		for (int i = 0; i < x.length; i++) {
			for (int j = 0; j < x[i].length; j++) {
				System.out.print(x[i][j] + " ");
			}
			System.out.println();
		}

		System.out.println(findMax(x));
	}

}

/*
 * A simple game of Tic Tac Toe!
 * 
 */
import java.util.Scanner;

public class TicTacToe {

	// This array stores the current state of the board.  Each element has
	//  one of three values:
	//  'X'
	//  'O'
	//  ' '  (for an empty spot)
	static char[][] theBoard = new char[3][3];

	// This method prints the current board on the screen.
	public static void printBoard() {
		for (int i = 0; i < theBoard.length; i++) {
			for (int j = 0; j < theBoard[i].length; j++) {
				System.out.print(theBoard[i][j] + " ");
			}
			System.out.println();
		}
	}

	// This method determines whether the game is still going.  It returns
	//  true if the game is in progress, or false if the game is over.
	public static boolean isGameStillGoing() {
		// Check for victory by X
		if (	theBoard[0][0] == 'X' && theBoard[0][1] == 'X' && theBoard[0][2] == 'X'	||
				theBoard[1][0] == 'X' && theBoard[1][1] == 'X' && theBoard[1][2] == 'X' ||
				theBoard[2][0] == 'X' && theBoard[2][1] == 'X' && theBoard[2][2] == 'X' ||
				theBoard[0][0] == 'X' && theBoard[1][0] == 'X' && theBoard[2][0] == 'X' ||
				theBoard[0][1] == 'X' && theBoard[1][1] == 'X' && theBoard[2][1] == 'X' ||
				theBoard[0][2] == 'X' && theBoard[1][2] == 'X' && theBoard[2][2] == 'X' ||
				theBoard[0][0] == 'X' && theBoard[1][1] == 'X' && theBoard[2][2] == 'X' ||
				theBoard[0][2] == 'X' && theBoard[1][1] == 'X' && theBoard[2][0] == 'X' ) {
			return false;
		}

		// Check for victory by O
		if (	theBoard[0][0] == 'O' && theBoard[0][1] == 'O' && theBoard[0][2] == 'O'	||
				theBoard[1][0] == 'O' && theBoard[1][1] == 'O' && theBoard[1][2] == 'O' ||
				theBoard[2][0] == 'O' && theBoard[2][1] == 'O' && theBoard[2][2] == 'O' ||
				theBoard[0][0] == 'O' && theBoard[1][0] == 'O' && theBoard[2][0] == 'O' ||
				theBoard[0][1] == 'O' && theBoard[1][1] == 'O' && theBoard[2][1] == 'O' ||
				theBoard[0][2] == 'O' && theBoard[1][2] == 'O' && theBoard[2][2] == 'O' ||
				theBoard[0][0] == 'O' && theBoard[1][1] == 'O' && theBoard[2][2] == 'O' ||
				theBoard[0][2] == 'O' && theBoard[1][1] == 'O' && theBoard[2][0] == 'O' ) {
			return false;
		}

		// Check for stalemate
		for (int i = 0; i < theBoard.length; i++) {
			for (int j = 0; j < theBoard[i].length; j++) {
				if (theBoard[i][j] == 0)	// Empty spaces left - game must still be going!
					return true;
			}
		}

		// The only way for this point to be reached is if the method hasn't
		//  returned anything yet.  This must mean that neither player has won,
		//  and there are no empty spaces left.  Must be a stalemate!
		return false;
	}

	// Run this method to play the game!
	public static void playGame() {
		Scanner s = new Scanner(System.in);

		while (isGameStillGoing()) {
			// Have player X move
			System.out.println("Player X's turn!");
			System.out.println("Enter the row and column where you'd like to make your move!");
			int row = s.nextInt(), col = s.nextInt();
			theBoard[row][col] = 'X';
			printBoard();

			// Player X's turn might have ended the game, so we need to check
			//  this condition immediately here.
			if (!isGameStillGoing())
				break;

			// Have player O move
			System.out.println("Player O's turn!");
			System.out.println("Enter the row and column where you'd like to make your move!");
			row = s.nextInt();
			col = s.nextInt();
			theBoard[row][col] = 'O';
			printBoard();
		}
	}

	public static void main(String[] args) {
//		theBoard[0][0] = 'X';
//		theBoard[0][2] = 'O';
//		theBoard[1][1] = 'X';
//		theBoard[2][2] = 'O';
//		theBoard[1][2] = 'O';
//		printBoard();
//		System.out.println(isGameStillGoing());

		playGame();
	}

}

/*
 * This class represents an Animal.  A class consists of two main parts:
 *  - Instance variables describe characteristics or qualities
 *  - Methods describe behaviors
 *  
 *  Once a class is defined, we can create objects (a.k.a. instances) of that
 *  class.  Each object of a class has its own values for the instance
 *  variables, and all objects of a class have access to that class' methods.
 */

public class Animal {

	// Instance variables - these are typically declared as private, meaning
	//  that they cannot be accessed directly from outside of this class.
	private String species;
	private boolean hasScales;
	private int numLegs;

	// Setter methods - these allow us to set values for instance variables.
	public void setSpecies(String s) {
		species = s;
	}

	public void setHasScales(boolean b) {
		hasScales = b;
	}

	public void setNumLegs(int n) {
		numLegs = n;
	}

	// Getter methods - these allow us to get/retrieve values for instance variables.
	public String getSpecies() {
		return species;
	}

	public boolean getHasScales() {
		return hasScales;
	}

	public int getNumLegs() {
		return numLegs;
	}

	// Constructor - this is called when first creating an object of this class.
	//  Constructors are often used to set values for instance variables, as
	//  shown here.
	public Animal(String s, boolean hs, int n) {
		setSpecies(s);
		setHasScales(hs);
		setNumLegs(n);
	}

	// Some other methods that Animal objects can call
	public void move() {
		System.out.println("The " + species + " is moving!");
	}

	public void breathe() {
		System.out.println("The " + species + " is ensuring its continued existence.");
	}

	public void mate() {
		System.out.println("The " + species + " is ensuring its continued existence, but in a more fun way.");
	}
}

