	scanf("%d", &previous);
	printf("Enter current meter reading> ");
	scanf("%d", &current);
use_charge = comp_use_charge(previous, current);
	late_charge = comp_late_charge(unpaid);
	bill = DEMAND_CHG + use_charge + unpaid + late_charge;
