double comp_use_charge(int previous, int current)
{
      int used;  
      double use_charge;  
      used = current - previous;
      use_charge = used * PER_1000_CHG;
      return (use_charge);
}
double comp_late_charge(double unpaid)
{
      double late_charge;
      if (unpaid > 0)
            late_charge = LATE_CHG; 
      else
            late_charge = 0.0;
      return (late_charge);
}
