public class RecursiveIsPalindrome{

    public static void main(String args[]){ 
        String str = "geeg"; 

        if (isPalindrome(str)) 
            System.out.println("Yes"); 
        else
            System.out.println("No"); 
    } 

     public boolean isPalindrome(String str) {
             if (str.length() <= 1) {
                 return true;
             }
             else{

                 if (str.charAt(0) != str.charAt(str.length() - 1)){
                     return false;
                 } 
                 else{

                     return isPalindrome(str.substring(1, str.length() - 1));
                }
            }
        }
    }
}

import java.util.Scanner;

public class BinarySearch {

   public static int binarySearch(int arr[], int first, int last, int lotNumber){

      int mid = (first + last)/2;

      while( first <= last ){

         if ( arr[mid] < lotNumber ){

            first = mid + 1;
         }

         else if ( arr[mid] == lotNumber ){  
            return mid;
         }

         else{

            last = mid - 1;
         }

         mid = (first + last)/2;
      }

      return -1;                    
   }

   public static void main(String a[]) {

      Scanner luckyNumber = new Scanner(System.in);

      int[] array = { 10, 20, 30, 40, 50, 60 };

      System.out.println("Enter your two digit lottery number: ");

      int lotNumber = luckyNumber.nextInt();

      int last=array.length-1;

      int index = binarySearch(array,0,last,lotNumber);

      if (index != -1) {

         index = index + 1;

         System.out.println(lotNumber + " is present at rank: " + index + " and the highest prize pull starts from '1' and then 2, 3 and so on.");

      } else {

         System.out.println("Sorry, Please Try Again!!!");
      }
   }
}

public class BubbleSort {

    static void Sorting(int[] list) {

        int n = list.length;
        int temp = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < (n - i); j++) {

                if (list[j - 1] > list[j]) { 

                    temp = list[j - 1]; 
                    list[j - 1] = list[j];
                    list[j] = temp;
                }
            }
        }

    }

    public static void main(String[] args) {

        int UnsortedList[] = {2, 5, -2, 6, -3, 8, 0, -7, -9, 4};
        System.out.println("Array Before Bubble Sort");

        for (int i = 0; i < UnsortedList.length; i++) {
            System.out.print(UnsortedList[i] + " ");
        }
        System.out.print('\n' + "Array after Bubble Sort" + '\n');

        Sorting(UnsortedList); 

        for (int i = 0; i < UnsortedList.length; i++) {
            System.out.print(UnsortedList[i] + " ");
        }

    }
}

