public class MatrixMultiply {
    public static void main(String[] args) {

        int r1 = 2, c1 = 2;
        int r2 = 2, c2 = 2;
        int[][] x = { {1,2},{3,4} };
        int[][] y = { {4,5}, {6,7} };
