int ascending( int a, int b );
int descending( int a, int b );
int main( void )
{
   int order;
   int counter;
   int a[ SIZE ] = { 2, 6, 4, 8, 10, 12, 89, 68, 45, 37 };
   printf( "Enter 1 to sort in ascending order,\n"
           "Enter 2 to sort in descending order: " );
