/* returns 1 if s is a palindrome, 0 otherwise */

int palindrome(char s[]) {
    int bottom, top;

    bottom = 0;
    top = strlen(s) - 1;
    while(bottom < top && s[bottom] == s[top]) {
        ++bottom;
        --top;
    }
    if(bottom >= top)
        return 1;
    else
        return 0;
}


